class ContentAnalyzer{constructor(){this.contentSelectors=["article",".post-content",".entry-content",".content","main",".main-content","#content",".post-body",".article-content"],this.titleSelectors=["h1",".post-title",".entry-title",".title","title"],this.metaSelectors=['meta[name="description"]','meta[property="og:description"]','meta[name="keywords"]']}extractContent(){const t={title:this.extractTitle(),text:this.extractText(),images:this.extractImages(),links:this.extractLinks(),meta:this.extractMeta(),wordCount:0,readingTime:0};return t.wordCount=this.calculateWordCount(t.text),t.readingTime=this.calculateReadingTime(t.wordCount),t}extractTitle(){for(const t of this.titleSelectors){const e=document.querySelector(t);if(e&&e.textContent&&e.textContent.trim())return e.textContent.trim()}return document.title||""}extractText(){let t="";for(const e of this.contentSelectors){const n=document.querySelector(e);if(n&&n.textContent&&(t=this.cleanText(n.textContent),t.length>100))break}if(!t||t.length<100){const e=document.body;e&&e.textContent&&(t=this.cleanText(e.textContent))}return t||""}extractImages(){const t=[];return document.querySelectorAll("img").forEach(e=>{e.src&&e.alt&&t.push({src:e.src,alt:e.alt,width:e.width,height:e.height})}),t}extractLinks(){const t=[];return document.querySelectorAll("a[href]").forEach(e=>{e.href&&e.textContent.trim()&&t.push({href:e.href,text:e.textContent.trim(),title:e.title||""})}),t}extractMeta(){const t={};return this.metaSelectors.forEach(e=>{const n=document.querySelector(e);if(n){const e=n.getAttribute("name")||n.getAttribute("property"),r=n.getAttribute("content");e&&r&&(t[e]=r)}}),t}cleanText(t){return t&&"string"==typeof t?t.replace(/\s+/g," ").replace(/\n+/g," ").replace(/\t+/g," ").trim():""}calculateWordCount(t){return t&&"string"==typeof t?t.split(/\s+/).filter(t=>t.length>0).length:0}calculateReadingTime(t){const e=t/225;return Math.ceil(e)}getContentType(){window.location.href;const t=window.location.pathname;return t.includes("/blog/")||t.includes("/post/")||t.includes("/article/")?"article":t.includes("/product/")||t.includes("/item/")?"product":t.includes("/category/")||t.includes("/tag/")?"category":"/"===t||""===t?"homepage":"page"}getContentTopics(){const t=this.extractText()||"",e=`${this.extractTitle()||""} ${t}`.toLowerCase(),n=[];return Object.entries({technology:["tech","software","programming","computer","digital","app","mobile"],business:["business","entrepreneur","startup","company","market","finance"],health:["health","medical","fitness","wellness","diet","exercise"],lifestyle:["lifestyle","fashion","beauty","travel","food","home"],education:["education","learning","study","course","tutorial","guide"]}).forEach(([t,r])=>{const o=r.filter(t=>e.includes(t)).length;o>0&&n.push({topic:t,confidence:o/r.length})}),n.sort((t,e)=>e.confidence-t.confidence),n}isContentReadable(){const t=this.extractText()||"";return this.calculateWordCount(t)>=50}}